import test from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';

import { createApp } from '../src/app';

test('health check route returns ok status', async () => {
  const app = createApp();

  const response = await request(app).get('/api/v1/health');

  assert.equal(response.status, 200);
  assert.deepEqual(response.body, { status: 'ok' });
});

test('unknown routes return a JSON 404 response', async () => {
  const app = createApp();

  const response = await request(app).get('/does-not-exist');

  assert.equal(response.status, 404);
  assert.equal(response.body.error, 'Route not found');
  assert.equal(response.body.status, 'error');
});

test('malformed payloads return a JSON 400 response', async () => {
  const app = createApp();

  app.post('/api/v1/test-validation', (req, res, next) => {
    if (!req.body?.name) {
      return next(new Error('Validation failed: name is required'));
    }

    return res.json({ ok: true });
  });

  const response = await request(app)
    .post('/api/v1/test-validation')
    .send({})
    .set('Content-Type', 'application/json');

  assert.equal(response.status, 400);
  assert.equal(response.body.error, 'Validation failed');
  assert.equal(response.body.status, 'error');
});

import { randomUUID } from 'node:crypto';
import pino from 'pino';

import { config } from '../config';

const isProduction = config.env === 'production';

const transport = isProduction
  ? undefined
  : pino.transport({
      target: 'pino-pretty',
      options: {
        colorize: true,
        translateTime: 'SYS:standard',
        ignore: 'pid,hostname',
      },
    });

export const logger = pino(
  {
    level: config.logLevel,
    timestamp: pino.stdTimeFunctions.isoTime,
    base: undefined,
    formatters: {
      level: (label) => ({ level: label }),
    },
    serializers: {
      req: (req: any) => ({
        id: req.id,
        method: req.method,
        url: req.originalUrl || req.url,
        route: req.route?.path,
        remoteAddress: req.socket?.remoteAddress,
        userAgent: req.headers?.['user-agent'],
      }),
      res: (res: any) => ({
        statusCode: res.statusCode,
      }),
    },
  },
  transport,
);

const redactHeaders = (headers: Record<string, any> = {}) => {
  const redacted: Record<string, any> = { ...headers };

  const sensitiveKeys = [
    'authorization',
    'cookie',
    'set-cookie',
    'x-api-key',
    'x-auth-token',
    'api-key',
    'apikey',
  ];

  for (const key of sensitiveKeys) {
    if (Object.prototype.hasOwnProperty.call(redacted, key)) {
      redacted[key] = '[REDACTED]';
    }
  }

  return redacted;
};

export const requestLogger = (req: any, res: any, next: () => void) => {
  const requestId = req.get?.('x-request-id') ?? randomUUID();
  const startedAt = Date.now();

  req.id = requestId;
  const childLogger = logger.child({
    requestId,
    request: {
      method: req.method,
      url: req.originalUrl || req.url,
      route: req.route?.path,
      remoteAddress: req.ip,
      userAgent: req.headers?.['user-agent'],
      headers: redactHeaders(req.headers),
    },
  });

  req.log = childLogger;
  res.locals.logger = childLogger;

  childLogger.info({ event: 'request_started' }, 'Request started');

  res.on('finish', () => {
    childLogger.info(
      {
        event: 'request_completed',
        statusCode: res.statusCode,
        durationMs: Date.now() - startedAt,
      },
      'Request completed',
    );
  });

  next();
};

import type { ErrorRequestHandler, Request, Response, NextFunction } from 'express';

import { config } from '../config';
import { logger } from '../lib/logger';

export class HttpError extends Error {
  statusCode: number;
  expose: boolean;

  constructor(statusCode: number, message: string, options: { expose?: boolean } = {}) {
    super(message);
    this.name = 'HttpError';
    this.statusCode = statusCode;
    this.expose = options.expose ?? true;
  }
}

export const asyncHandler =
  (handler: (req: Request, res: Response, next: NextFunction) => Promise<unknown> | unknown) =>
  (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(handler(req, res, next)).catch(next);
  };

const isValidationError = (error: unknown): boolean => {
  if (error instanceof HttpError && error.statusCode === 400) {
    return true;
  }

  if (error instanceof Error) {
    return (
      error.name === 'ValidationError' ||
      /validation failed/i.test(error.message) ||
      /required/i.test(error.message) ||
      /invalid.*(body|payload|request)/i.test(error.message)
    );
  }

  return false;
};

const getErrorMessage = (error: unknown, fallback: string): string => {
  if (error instanceof Error && error.message.trim()) {
    return error.message;
  }

  return fallback;
};

const getStatusCode = (error: unknown): number => {
  if (error instanceof HttpError) {
    return error.statusCode;
  }

  if (error instanceof SyntaxError && 'body' in error) {
    return 400;
  }

  if (isValidationError(error)) {
    return 400;
  }

  return 500;
};

export const notFoundHandler = (req: Request, res: Response, next: NextFunction) => {
  next(new HttpError(404, 'Route not found'));
};

export const errorHandler: ErrorRequestHandler = (error, req, res, _next) => {
  const requestLogger = (req as any).log ?? logger;
  const statusCode = getStatusCode(error);

  if (statusCode >= 500) {
    requestLogger.error(
      {
        err: error,
        request: {
          method: req.method,
          url: req.originalUrl,
          route: req.route?.path,
          requestId: (req as any).id,
        },
      },
      'Unhandled server error',
    );
  } else {
    requestLogger.warn(
      {
        err: error,
        request: {
          method: req.method,
          url: req.originalUrl,
          route: req.route?.path,
          requestId: (req as any).id,
        },
      },
      'Request error handled',
    );
  }

  const safeError =
    statusCode === 404
      ? 'Route not found'
      : statusCode === 400
        ? 'Validation failed'
        : statusCode === 401
          ? 'Unauthorized'
          : statusCode === 403
            ? 'Forbidden'
            : statusCode === 429
              ? 'Too many requests'
              : 'Internal server error';

  const safeMessage =
    statusCode === 404
      ? 'The requested route does not exist.'
      : statusCode === 400
        ? getErrorMessage(error, 'The request is invalid.')
        : statusCode === 401
          ? 'Authentication is required to access this resource.'
          : statusCode === 403
            ? 'You do not have permission to perform this action.'
            : statusCode === 429
              ? 'Too many requests. Please try again later.'
              : 'Something went wrong on the server.';

  const responseBody: Record<string, unknown> = {
    status: 'error',
    error: safeError,
    message: safeMessage,
  };

  if (config.env !== 'production' && statusCode >= 500 && error instanceof Error && error.stack) {
    responseBody.stack = error.stack;
  }

  return res.status(statusCode).json(responseBody);
};

import { errorHandler, notFoundHandler } from './middleware/errorHandler';
import { requestLogger } from './lib/logger';

export const createApp = () => {
  const app = express();

  app.disable('x-powered-by');
  app.use(express.json({ limit: '1mb' }));
  app.use(requestLogger);

  app.get('/api/v1/health', (_req, res) => {
    res.json({ status: 'ok' });
  });

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
};

