{
  "name": "opentext-markdown-converter-ui",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^4.3.1",
    "vite": "^5.4.10"
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    host: '0.0.0.0',
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true,
      },
    },
  },
  preview: {
    port: 4173,
    host: '0.0.0.0',
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './styles.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import { useMemo, useState } from 'react';

const initialResult = {
  sourceUrl: '',
  contentType: 'text/markdown',
  title: '',
  markdown: '',
};

function App() {
  const [url, setUrl] = useState('');
  const [result, setResult] = useState(initialResult);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);

  const downloadName = useMemo(() => {
    const base = (result.title || 'article').trim();
    const safe = base.replace(/[^a-z0-9-_ ]/gi, '').replace(/\s+/g, '-').toLowerCase() || 'article';
    return `${safe}.md`;
  }, [result.title]);

  const handleConvert = async (event) => {
    event.preventDefault();

    if (!url.trim()) {
      setError('Please enter an article URL to convert.');
      setResult(initialResult);
      return;
    }

    setLoading(true);
    setError('');
    setCopied(false);

    try {
      const response = await fetch('/api/v1/convert', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'text/markdown',
        },
        body: JSON.stringify({ url: url.trim() }),
      });

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(data?.message || data?.error || 'Conversion failed. Please try again.');
      }

      if (!data || typeof data.markdown !== 'string') {
        throw new Error('The server response was missing markdown content.');
      }

      setResult({
        sourceUrl: data.sourceUrl || url.trim(),
        contentType: data.contentType || 'text/markdown',
        title: data.title || 'Untitled article',
        markdown: data.markdown,
      });
    } catch (conversionError) {
      setError(conversionError.message || 'Something went wrong while converting the article.');
      setResult(initialResult);
    } finally {
      setLoading(false);
    }
  };

  const handleCopy = async () => {
    if (!result.markdown) {
      return;
    }

    try {
      await navigator.clipboard.writeText(result.markdown);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {
      setError('Copy failed. Please select and copy the markdown manually.');
    }
  };

  const handleDownload = () => {
    if (!result.markdown) {
      return;
    }

    const blob = new Blob([result.markdown], { type: 'text/markdown;charset=utf-8' });
    const urlObject = URL.createObjectURL(blob);
    const anchor = document.createElement('a');

    anchor.href = urlObject;
    anchor.download = downloadName;
    document.body.appendChild(anchor);
    anchor.click();
    document.body.removeChild(anchor);
    URL.revokeObjectURL(urlObject);
  };

  return (
    <div className="app-shell">
      <div className="panel">
        <header className="header">
          <div>
            <p className="eyebrow">OpenText</p>
            <h1>Markdown Converter</h1>
          </div>
        </header>

        <form className="converter-form" onSubmit={handleConvert}>
          <label htmlFor="article-url" className="label">
            Article URL
          </label>
          <div className="input-row">
            <input
              id="article-url"
              type="url"
              value={url}
              onChange={(event) => setUrl(event.target.value)}
              placeholder="https://my.opentext.com/article/12345"
              aria-label="Article URL"
            />
            <button type="submit" className="primary-button" disabled={loading}>
              {loading ? 'Converting...' : 'Convert'}
            </button>
          </div>
        </form>

        {error && <div className="message error-message">{error}</div>}

        <section className="result-card">
          <div className="meta-row">
            <div>
              <span className="meta-label">Source</span>
              <p>{result.sourceUrl || 'Not available yet'}</p>
            </div>
            <div>
              <span className="meta-label">Title</span>
              <p>{result.title || 'Waiting for conversion'}</p>
            </div>
            <div>
              <span className="meta-label">Content type</span>
              <p>{result.contentType || 'text/markdown'}</p>
            </div>
          </div>

          <div className="actions-row">
            <button
              type="button"
              className="secondary-button"
              onClick={handleCopy}
              disabled={!result.markdown}
            >
              {copied ? 'Copied!' : 'Copy'}
            </button>
            <button
              type="button"
              className="secondary-button"
              onClick={handleDownload}
              disabled={!result.markdown}
            >
              Download .md
            </button>
          </div>

          <div className="output-shell">
            {loading ? (
              <div className="empty-state">Converting article to Markdown...</div>
            ) : result.markdown ? (
              <pre>{result.markdown}</pre>
            ) : (
              <div className="empty-state">The converted Markdown will appear here.</div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
}

export default App;

