:root {
  color-scheme: light dark;
  --bg: #f5f7fb;
  --panel: #ffffff;
  --panel-alt: #f8fafc;
  --surface: #eef4ff;
  --border: #d9e1ef;
  --border-strong: #c8d4ea;
  --text: #1f2937;
  --muted: #5d6b82;
  --accent: #2f6fed;
  --accent-strong: #2258c9;
  --error: #c92a2a;
  --shadow: rgba(15, 23, 42, 0.08);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f172a;
    --panel: #111827;
    --panel-alt: #171f2f;
    --surface: #111b2d;
    --border: #2c3b52;
    --border-strong: #41557b;
    --text: #ebf2ff;
    --muted: #a5b4cf;
    --accent: #6aa5ff;
    --accent-strong: #8ab7ff;
    --error: #ff7d7d;
    --shadow: rgba(2, 6, 23, 0.4);
  }
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, 'Segoe UI', sans-serif;
  line-height: 1.5;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
code,
pre,
textarea,
select {
  font: inherit;
}

button,
input {
  border-radius: 6px;
}

.container {
  width: min(1100px, calc(100% - 48px));
  margin: 0 auto;
  padding: 0 24px;
}

.top-nav {
  background: rgba(255, 255, 255, 0.8);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}

@media (prefers-color-scheme: dark) {
  .top-nav {
    background: rgba(15, 23, 42, 0.82);
  }
}

.nav-inner {
  display: flex;
  align-items: center;
  min-height: 64px;
  padding: 0 24px;
}

.nav-links {
  display: flex;
  gap: 20px;
}

.nav-link {
  color: var(--muted);
  font-weight: 500;
  padding: 10px 0;
  border-bottom: 2px solid transparent;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.nav-link.active {
  color: var(--text);
  font-weight: 700;
  border-color: var(--accent);
}

.page-shell,
.docs-page {
  padding: 32px 0 56px;
}

.page-header {
  margin-bottom: 20px;
}

.page-header h1,
.docs-section h1,
.docs-section h2,
.meta-panel h2 {
  margin: 0 0 16px;
  line-height: 1.2;
}

.page-header h1,
.docs-section h1 {
  font-size: clamp(2rem, 2.5vw, 2.5rem);
}

.converter-form {
  margin-bottom: 18px;
}

.input-row {
  display: flex;
  gap: 12px;
  align-items: center;
}

.text-input {
  flex: 1;
  min-width: 0;
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px 14px;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.text-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(47, 111, 237, 0.12);
}

.primary-button,
.secondary-button,
.tab-button {
  appearance: none;
  border: 1px solid var(--border);
  background: var(--panel);
  color: var(--text);
  border-radius: 6px;
  padding: 10px 14px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease;
}

.primary-button {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  min-width: 144px;
}

.primary-button:hover,
.secondary-button:hover,
.tab-button:hover {
  border-color: var(--border-strong);
}

.primary-button:disabled,
.secondary-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error-message {
  margin: 0 0 18px;
  padding: 10px 12px;
  border: 1px solid rgba(201, 42, 42, 0.3);
