}

.markdown-card,
.meta-panel,
.docs-sidebar,
.docs-content > .docs-section {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 8px 18px var(--shadow);
}

.markdown-card {
  overflow: hidden;
}

.card-toolbar {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--panel-alt);
}

.tab-group,
.action-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.tab-button {
  background: transparent;
  border-color: transparent;
}

.tab-button.active {
  background: var(--surface);
  border-color: var(--border);
  color: var(--accent-strong);
}

.card-body {
  min-height: 360px;
  padding: 18px;
}

.markdown-output,
.rendered-markdown {
  margin: 0;
  min-height: 300px;
  line-height: 1.7;
  color: var(--text);
}

.markdown-output {
  background: #f3f4f6;
