  border-radius: 8px;
  border: 1px solid var(--border);
  padding: 16px;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
  font-size: 0.9rem;
}

.rendered-markdown {
  background: transparent;
}

.rendered-markdown h1,
.rendered-markdown h2,
.rendered-markdown h3,
.rendered-markdown h4,
.rendered-markdown h5,
.rendered-markdown h6 {
  margin-top: 1.2em;
  margin-bottom: 0.7em;
  line-height: 1.25;
}

.rendered-markdown p,
.rendered-markdown ul,
.rendered-markdown ol,
.rendered-markdown blockquote,
.rendered-markdown pre,
.rendered-markdown table {
  margin-top: 0;
  margin-bottom: 1em;
}

.rendered-markdown pre,
.rendered-markdown code {
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
}

.rendered-markdown pre {
  background: #f3f4f6;
  color: #1f2937;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 14px;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.rendered-markdown code {
  background: #f3f4f6;
  border-radius: 4px;
  padding: 0.12em 0.38em;
  font-size: 0.9em;
}

.rendered-markdown table {
  width: 100%;
  border-collapse: collapse;
}

.rendered-markdown th,
.rendered-markdown td {
  border: 1px solid var(--border);
  padding: 8px 10px;
  text-align: left;
}

.meta-panel {
  padding: 18px 16px;
}

.metadata-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.metadata-list li {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.metadata-list li:last-child {
  border-bottom: none;
}

.metadata-list span {
  color: var(--muted);
  font-size: 0.77rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.metadata-list strong {
  font-weight: 600;
  line-height: 1.5;
  word-break: break-word;
}

.docs-layout {
  display: grid;
  grid-template-columns: 225px minmax(0, 1fr);
  gap: 24px;
  align-items: flex-start;
}

.docs-sidebar {
  position: sticky;
  top: 88px;
  padding: 14px;
}

.docs-nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.docs-link {
  color: var(--muted);
  padding: 8px 10px;
  border-radius: 6px;
  font-weight: 600;
}

.docs-link:hover {
  background: var(--panel-alt);
  color: var(--text);
}

.docs-content {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.docs-section {
  padding: 22px 20px;
}

.docs-section h2 {
  font-size: clamp(1.35rem, 1.8vw, 1.7rem);
}

.docs-section p,
.docs-section li,
.docs-section code {
  font-size: 1rem;
}

.code-block {
  background: #f3f4f6;
  color: #111827;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 14px;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.docs-section code {
  background: #f3f4f6;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.12em 0.35em;
}

.docs-section table,
.docs-section th,
.docs-section td {
  border: 1px solid var(--border);
  border-collapse: collapse;
}

.docs-section th,
.docs-section td {
  padding: 8px 10px;
  text-align: left;
}

@media (max-width: 760px) {
  .container {
    width: min(100% - 24px, 1100px);
    padding: 0 12px;
  }

  .nav-inner {
    padding: 0 12px;
  }

  .preview-layout,
  .docs-layout {
    grid-template-columns: 1fr;
  }

  .docs-sidebar {
    position: static;
  }

  .input-row,
  .card-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .primary-button,
  .secondary-button,
  .tab-button {
    width: 100%;
  }

  .action-group,
  .tab-group {
    width: 100%;
  }
}

