              type="url"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              required
            />
            <button className="primary-button" disabled={loading}>
              {loading ? 'Converting…' : 'Convert'}
            </button>
          </div>
        </form>

        {error && <p className="error-message">{error}</p>}

        {markdown && (
          <div className="preview-layout">
            <div className="markdown-card">
              <div className="card-toolbar">
                <div className="tab-group">
                  <button
                    type="button"
                    className={raw ? 'tab-button' : 'tab-button active'}
                    onClick={() => setRaw(false)}
                  >
                    Preview
                  </button>
                  <button
                    type="button"
                    className={raw ? 'tab-button active' : 'tab-button'}
                    onClick={() => setRaw(true)}
                  >
                    Markdown
                  </button>
                </div>
                <div className="action-group">
                  <button type="button" className="secondary-button" onClick={() => navigator.clipboard.writeText(markdown)}>
                    Copy
                  </button>
                  <button type="button" className="secondary-button" onClick={download}>
                    Download .md
                  </button>
                </div>
              </div>

              <div className="card-body">
                {raw ? (
                  <pre className="markdown-output">{markdown}</pre>
                ) : (
                  <article className="rendered-markdown">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{body}</ReactMarkdown>
                  </article>
                )}
              </div>
            </div>

            <aside className="meta-panel">
              <h2>Article metadata</h2>
              <ul className="metadata-list">
                {Object.entries(metadata)
                  .filter(([key]) => key !== 'products')
                  .map(([key, value]) => (
                    <li key={key}>
                      <span>{key}</span>
                      <strong>{typeof value === 'object' ? JSON.stringify(value) : String(value)}</strong>
                    </li>
                  ))}
              </ul>
            </aside>
          </div>
        )}
      </div>
    </main>
  );
}"},{"filePath":"/home/apollo87z/opentext-markdown-converter-assessment/frontend/src/Docs.jsx","oldString":"export default function Docs() {
