     1  import { useState } from 'react';
     2  import ReactMarkdown from 'react-markdown';
     3  import remarkGfm from 'remark-gfm';
     4  import { parseMarkdownMetadata } from './utils/markdown';
     5
     6  export default function LivePreview() {
     7    const [url, setUrl] = useState('https://my.opentext.com/support/article/1986936');
     8    const [markdown, setMarkdown] = useState('');
     9    const [raw, setRaw] = useState(false);
    10    const [error, setError] = useState('');
    11    const [loading, setLoading] = useState(false);
    12
    13    const { metadata, body } = parseMarkdownMetadata(markdown);
    14
    15    const convert = async (event) => {
    16      event.preventDefault();
    17      setLoading(true);
    18      setError('');
    19
    20      try {
    21        const res = await fetch('/api/v1/convert', {
    22          method: 'POST',
    23          headers: { 'Content-Type': 'application/json', Accept: 'text/markdown' },
    24          body: JSON.stringify({ url }),
    25        });
    26        const text = await res.text();
    27        if (!res.ok) throw new Error(JSON.parse(text).message);
    28        setMarkdown(text);
    29      } catch (err) {
    30        setMarkdown('');
    31        setError(err.message);
    32      } finally {
    33        setLoading(false);
    34      }
    35    };
    36
    37    const download = () => {
    38      const link = document.createElement('a');
    39      link.href = URL.createObjectURL(new Blob([markdown], { type: 'text/markdown' }));
    40      link.download = 'article.md';
    41      link.click();
    42      URL.revokeObjectURL(link.href);
    43    };
    44
    45    return (
    46      <main className="page-shell">
    47        <div className="container">
    48          <section className="page-header">
    49            <h1>Live Preview</h1>
    50          </section>
    51
    52          <form className="converter-form" onSubmit={convert}>
    53            <div className="input-row">
    54              <input
    55                className="text-input"
    56                type="url"
    57                value={url}
    58                onChange={(e) => setUrl(e.target.value)}
    59                required
    60              />
    61              <button className="primary-button" disabled={loading}>
    62                {loading ? 'Converting…' : 'Convert'}
    63              </button>
    64            </div>
    65          </form>
    66
    67          {error && <p className="error-message">{error}</p>}
    68
    69          {markdown && (
    70            <div className="preview-layout">
    71              <div className="markdown-card">
    72                <div className="card-toolbar">
    73                  <div className="tab-group">
    74                    <button
    75                      type="button"
    76                      className={raw ? 'tab-button' : 'tab-button active'}
    77                      onClick={() => setRaw(false)}
    78                    >
    79                      Preview
    80                    </button>
    81                    <button
    82                      type="button"
    83                      className={raw ? 'tab-button active' : 'tab-button'}
    84                      onClick={() => setRaw(true)}
    85                    >
    86                      Markdown
    87                    </button>
    88                  </div>
    89                  <div className="action-group">
    90                    <button type="button" className="secondary-button" onClick={() => navigator.clipboard.writeText(markdown)}>
    91                      Copy
    92                    </button>
    93                    <button type="button" className="secondary-button" onClick={download}>
    94                      Download .md
    95                    </button>
    96                  </div>
    97                </div>
    98
    99                <div className="card-body">
   100                  {raw ? (
   101                    <pre className="markdown-output">{markdown}</pre>
   102                  ) : (
   103                    <article className="rendered-markdown">
   104                      <ReactMarkdown remarkPlugins={[remarkGfm]}>{body}</ReactMarkdown>
   105                    </article>
   106                  )}
   107                </div>
   108              </div>
   109
   110              <aside className="meta-panel">
   111                <h2>Article metadata</h2>
   112                <ul className="metadata-list">
   113                  {Object.entries(metadata)
   114                    .filter(([key]) => key !== 'products')
   115                    .map(([key, value]) => (
   116                      <li key={key}>
   117                        <span>{key}</span>
   118                        <strong>{typeof value === 'object' ? JSON.stringify(value) : String(value)}</strong>
   119                      </li>
   120                    ))}
   121                </ul>
   122              </aside>
   123            </div>
   124          )}
   125        </div>
   126      </main>
   127    );
   128  }

