    return false;
  }

  if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
    return Number(trimmed);
  }

  return trimmed;
}

function parseStructuredValue(lines, startIndent = 0) {
  const normalizedLines = lines
    .filter((line) => typeof line === 'string')
    .map((line) => line.replace(/\t/g, '  '))
    .filter((line) => line.trim())
    .map((line) => ({
      raw: line.trim(),
      indent: (line.match(/^\s*/)?.[0].length ?? 0) - startIndent,
    }));

  if (!normalizedLines.length) {
    return [];
  }

  const firstIndent = normalizedLines[0].indent;
  const isSequence = normalizedLines.every(
    ({ raw, indent }) => indent === firstIndent && raw.startsWith('- '),
  );

  if (isSequence) {
    const items = [];
    let index = 0;

    while (index < normalizedLines.length) {
      const { raw } = normalizedLines[index];
      const trimmed = raw.trim();

      if (!trimmed.startsWith('- ')) {
        index += 1;
        continue;
      }

      const remainder = trimmed.slice(2).trim();
      index += 1;

      if (!remainder) {
        const nestedLines = [];

        while (index < normalizedLines.length && normalizedLines[index].indent > firstIndent) {
          nestedLines.push(normalizedLines[index].raw);
          index += 1;
        }

        items.push(parseStructuredValue(nestedLines, firstIndent + 2));
        continue;
      }

      const inlineMatch = remainder.match(/^([^:]+):\s*(.*)$/);

      if (inlineMatch && !remainder.startsWith('[') && !remainder.startsWith('{')) {
        const [, key, rawValue] = inlineMatch;
        const item = {};

        if (rawValue.trim() === '') {
          const nestedLines = [];

          while (index < normalizedLines.length && normalizedLines[index].indent > firstIndent) {
            nestedLines.push(normalizedLines[index].raw);
            index += 1;
          }

          item[key] = parseStructuredValue(nestedLines, firstIndent + 2);
        } else {
          item[key] = parseScalar(rawValue);
        }

        while (index < normalizedLines.length) {
          const next = normalizedLines[index];

          if (next.indent <= firstIndent || next.raw.trim().startsWith('- ')) {
            break;
          }

          const nextMatch = next.raw.trim().match(/^([^:]+):\s*(.*)$/);

          if (!nextMatch) {
            index += 1;
            continue;
          }

          const [, nextKey, nextRawValue] = nextMatch;
          index += 1;

          if (nextRawValue.trim() === '') {
            const nestedLines = [];

            while (index < normalizedLines.length && normalizedLines[index].indent > next.indent) {
              nestedLines.push(normalizedLines[index].raw);
              index += 1;
            }

            item[nextKey] = parseStructuredValue(nestedLines, next.indent + 2);
          } else {
            item[nextKey] = parseScalar(nextRawValue);
          }
        }

        items.push(item);
        continue;
      }

      items.push(parseScalar(remainder));
    }

    return items;
  }

  const object = {};
  let index = 0;

  while (index < normalizedLines.length) {
    const { raw, indent } = normalizedLines[index];

    if (indent !== firstIndent) {
      index += 1;
      continue;
    }

    const match = raw.match(/^([^:]+):\s*(.*)$/);

    if (!match) {
      index += 1;
      continue;
    }

    const [, key, rawValue] = match;
    index += 1;

    if (rawValue.trim() === '') {
      const nestedLines = [];

      while (index < normalizedLines.length && normalizedLines[index].indent > firstIndent) {
        nestedLines.push(normalizedLines[index].raw);
        index += 1;
      }

      object[key] = nestedLines.length ? parseStructuredValue(nestedLines, firstIndent + 2) : '';
    } else {
      object[key] = parseScalar(rawValue);
    }
  }

  return object;
}

export function parseMarkdownMetadata(markdown = '') {
  const normalized = markdown ?? '';

  if (!normalized.trim().startsWith('---')) {
