test('attachment metadata resolves relative URLs and nulls foreign URLs', async () => {
  await withMockedFetch(
    async () =>
      successResponse({
        Title: 'Attachment article',
        Attachments: [
          { id: '1', name: 'a[1].pdf', url: '/files/a[1].pdf', contentType: 'application/pdf', size: 1234, isExternalAttachment: false },
          { id: '2', name: 'same.pdf', url: 'https://my.opentext.com/files/same.pdf', contentType: 'application/pdf', size: 2345, isExternalAttachment: false },
          { id: '3', name: 'foreign.pdf', url: 'https://evil.com/files/foreign.pdf', contentType: 'application/pdf', size: 3456, isExternalAttachment: true },
          { id: '4', name: 'foreign-fileurl.pdf', fileUrl: 'https://evil.com/files/fileurl.pdf', contentType: 'application/pdf', size: 4567, isExternalAttachment: true },
          { id: '5', name: 'bad.pdf', url: 'http://[bad', contentType: 'application/pdf', size: 5678, isExternalAttachment: false },
        ],
      }) as Response,
    async () => {
      const response = await request(buildApp())
        .post('/convert')
        .set('Accept', 'application/json')
        .send({ url: articleUrl });

      assert.equal(response.status, 200);
      assert.equal(response.body.article.attachments.length, 5);
      assert.equal(response.body.article.attachments[0].url, 'https://my.opentext.com/files/a%5B1%5D.pdf');
      assert.equal(response.body.article.attachments[1].url, 'https://my.opentext.com/files/same.pdf');
      assert.equal(response.body.article.attachments[2].url, null);
      assert.equal(response.body.article.attachments[3].url, null);
      assert.equal(response.body.article.attachments[4].url, null);
      assert.match(response.body.markdown, /a\[1\]\.pdf/);
      assert.match(response.body.markdown, /%5B1%5D/);
      assert.doesNotMatch(response.body.markdown, /foreign\.pdf/);
      assert.doesNotMatch(response.body.markdown, /foreign-fileurl\.pdf/);
    },
  );
});

