import { useMemo, useState } from 'react';

function TokenizedCode({ code, language }) {
  const rendered = useMemo(() => {
    const pattern =
      /((?:\"(?:\\.|[^\"\\])*\"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`)|\/\/.*|#.*|true|false|null|\b(?:const|let|var|await|async|import|from|return|if|else|for|while|try|catch|class|def|print|curl|GET|POST|Accept|Content-Type|application|json)\b|\b\d+(?:\.\d+)?\b|[{}\[\]():,])|\s+|\S+/g;

    const segments = [];
    let lastIndex = 0;
    let match;

    while ((match = pattern.exec(code)) !== null) {
      if (match.index > lastIndex) {
        segments.push(
          <span key={`plain-${lastIndex}`} className="token-plain">
            {code.slice(lastIndex, match.index)}
          </span>,
        );
      }

      const token = match[0];
      let className = 'token-default';

      if (/^(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`)$/.test(token)) {
        className = 'token-string';
      } else if (/^(?:true|false|null)$/.test(token)) {
        className = 'token-boolean';
      } else if (/^\d+(?:\.\d+)?$/.test(token)) {
        className = 'token-number';
      } else if (/^(?:\/\/.*|#.*)$/.test(token)) {
        className = 'token-comment';
      } else if (/^(?:const|let|var|await|async|import|from|return|if|else|for|while|try|catch|class|def|print|curl|GET|POST|Accept|Content-Type|application|json)$/.test(token)) {
        className = 'token-keyword';
      } else if (/^[{}\[\]():,]$/.test(token)) {
        className = 'token-punctuation';
      }

      segments.push(
        <span key={`token-${match.index}`} className={className}>
          {token}
        </span>,
      );

      lastIndex = match.index + token.length;
    }

    if (lastIndex < code.length) {
      segments.push(
        <span key={`tail-${lastIndex}`} className="token-plain">
          {code.slice(lastIndex)}
        </span>,
      );
    }

    return segments;
  }, [code, language]);

  return <code className="code-content">{rendered}</code>;
}

function CodeExamplePanel({ examples }) {
  const [activeLanguage, setActiveLanguage] = useState(examples[0]?.language ?? 'bash');
  const activeExample = examples.find((example) => example.language === activeLanguage) ?? examples[0];

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(activeExample.code);
      const button = document.activeElement;
      if (button && button instanceof HTMLButtonElement) {
        button.dataset.copied = 'true';
      }
      setTimeout(() => {
        const copyButton = document.querySelector('.docs-copy-button[data-copied="true"]');
        if (copyButton) {
          copyButton.dataset.copied = 'false';
        }
      }, 1200);
    } catch (error) {
      console.error('Unable to copy code block:', error);
    }
  };

  return (
