}

.docs-section h2 {
  margin: 0;
  font-size: clamp(1.5rem, 2vw, 2rem);
  line-height: 1.2;
  letter-spacing: -0.03em;
}

.docs-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 12px;
}

.docs-section p,
.docs-section li,
.docs-section code,
.docs-section td,
.docs-section th {
  font-size: 0.98rem;
}

.docs-section p {
  color: var(--text);
  line-height: 1.7;
}

.docs-section ul {
  margin: 16px 0 0;
  padding-left: 1.2rem;
  color: var(--text);
  line-height: 1.7;
}

.docs-route-table {
