  border-collapse: collapse;
  margin-top: 18px;
  background: var(--panel-alt);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}

.docs-route-table th,
.docs-route-table td {
  padding: 12px 14px;
  text-align: left;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.docs-route-table th {
  background: var(--surface);
  font-weight: 700;
}

.docs-route-table tr:last-child td {
  border-bottom: none;
}

.docs-code-panel {
  margin-top: 18px;
  border: 1px solid var(--border-strong);
  border-radius: 12px;
  background: #0f172a;
  box-shadow: inset 0 1px 0 rgba(148, 163, 184, 0.12);
  overflow: hidden;
}

.docs-code-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px 8px;
  background: rgba(15, 23, 42, 0.92);
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.docs-code-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  overflow-x: auto;
  scrollbar-width: thin;
}

.docs-tab {
  appearance: none;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: transparent;
  color: #cbd5e1;
  border-radius: 8px;
  padding: 7px 10px;
  font-weight: 600;
  font-size: 0.8rem;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.docs-tab:hover {
  border-color: rgba(148, 163, 184, 0.42);
}

.docs-tab.active {
  background: rgba(96, 165, 250, 0.12);
  border-color: rgba(96, 165, 250, 0.5);
  color: #e2e8f0;
}

.docs-copy-button {
  appearance: none;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.8);
  color: #e2e8f0;
  border-radius: 8px;
  padding: 7px 10px;
  font-weight: 700;
  font-size: 0.78rem;
  line-height: 1;
  cursor: pointer;
  transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
}

.docs-copy-button:hover {
  border-color: rgba(148, 163, 184, 0.45);
  background: rgba(15, 23, 42, 1);
}

.docs-copy-button:active {
  transform: translateY(1px);
}

.docs-code-container {
  margin: 0;
  background: #0f172a;
  color: #e2e8f0;
  overflow-x: auto;
}

.code-content {
  display: block;
  margin: 0;
  padding: 16px 18px;
  min-height: 120px;
  white-space: pre;
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
  font-size: 0.86rem;
  line-height: 1.65;
  color: #e2e8f0;
}

.token-default { color: #e2e8f0; }
.token-string { color: #7dd3fc; }
.token-number { color: #fbbf24; }
.token-keyword { color: #c084fc; }
.token-boolean { color: #fca5a5; }
.token-comment { color: #64748b; }
.token-punctuation { color: #cbd5e1; }

.docs-section code {
  background: #f3f4f6;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.12em 0.4em;
  color: #0f172a;
}

.docs-section table,
.docs-section th,
.docs-section td {
  border: 1px solid var(--border);
  border-collapse: collapse;
}

.docs-section th,
.docs-section td {
  padding: 8px 10px;
  text-align: left;
}

@media (max-width: 760px) {
  .docs-layout {
    grid-template-columns: 1fr;
  }

  .docs-sidebar {
    position: static;
    top: auto;
  }

  .docs-content {
    gap: 18px;
  }

