    padding: 18px 16px;
  }

  .docs-code-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .docs-copy-button {
    align-self: flex-end;
  }

  .docs-code-tabs {
    width: 100%;
  }

  .docs-tab {
    flex: 1 1 auto;
    text-align: center;
  }

  .code-content {
    min-width: 560px;
  }
}
